import heapq


def alien_order(words):
    chars = set()
    for w in words:
        for c in w:
            chars.add(c)
    adj = {c: set() for c in chars}
    indegree = {c: 0 for c in chars}
    for i in range(len(words) - 1):
        a, b = words[i], words[i + 1]
        minlen = min(len(a), len(b))
        found = False
        for j in range(minlen):
            if a[j] != b[j]:
                if b[j] not in adj[a[j]]:
                    adj[a[j]].add(b[j])
                    indegree[b[j]] += 1
                found = True
                break
        if not found and len(a) > len(b):
            return ""
    heap = [c for c in chars if indegree[c] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        c = heapq.heappop(heap)
        order.append(c)
        for nxt in sorted(adj[c]):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)
    if len(order) != len(chars):
        return ""
    return "".join(order)
